// parent: the order process of SPEC-E (E8). It routes each event to the sub-workflow that owns it, keeps the order's
// record in its own state (fulfilment statuses, cleared or ended, the collection reports of R6.2) and asks the
// modules for what the rules require. Modules keep their own state; the parent reads only their outputs.

const TERMINAL = ['completed', 'failed', 'cancelled'];
const COLLECTED = ['collected', 'inTransit', 'delivered'];           // S7: reports that prove collection
const PHASE_STATUS = { reserving: 'processing', charging: 'processing', shipping: 'processing', shipped: 'processing',
  dispatched: 'dispatched', completed: 'completed', failed: 'failed', cancelled: 'cancelled' };

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const ms = s => Date.parse(s);
const norm = s => String(s ?? '').trim().replace(/^#/, '').trim().toUpperCase();     // SPEC §3.1
const jsonOf = f => (typeof f === 'string' ? JSON.parse(f) : (f ?? null));
const rowsOf = r => (Array.isArray(r) ? r : (isObj(r) && Array.isArray(r.rows) ? r.rows : []));

// The API may rename a field: api/<system>.schema.json in ctx.files shows the current names, so send those.
const fitNorm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
function fitArgs(e, files) {
  const props = jsonOf(files?.[`api/${e.system}.schema.json`])?.ops?.[e.op]?.args?.properties;
  if (!props || !isObj(e.args)) return e;
  const names = Object.keys(props);
  const keys = Object.keys(e.args);
  const extra = keys.filter(k => !names.includes(k));
  const missing = names.filter(n => !keys.includes(n));
  const renamed = {};
  for (const k of extra) renamed[k] = names.find(n => fitNorm(n) === fitNorm(k)) ?? (extra.length === 1 && missing.length === 1 ? missing[0] : k);
  const args = {};
  for (const k of keys) args[renamed[k] ?? k] = e.args[k];
  return { ...e, args };
}

// A lookup table from a master or rulebook file: a list of rows, or an object keyed by the key itself.
function mapOf(x, keys, vals) {
  const out = {};
  const list = Array.isArray(x) ? x : (isObj(x) ? Object.values(x).find(Array.isArray) : null);
  if (list) {
    for (const r of list) {
      const k = keys.map(n => r?.[n]).find(v => v !== undefined);
      const v = vals.map(n => r?.[n]).find(z => z !== undefined);
      if (k !== undefined && v !== undefined) out[k] = v;
    }
  } else if (isObj(x)) {
    for (const [k, v] of Object.entries(x)) out[k] = isObj(v) ? vals.map(n => v[n]).find(z => z !== undefined) : v;
  }
  return out;
}

// R1.3: the published edition with the latest effectiveFrom on or before the date of p (Amsterdam local date).
function editionAt(ctx, placedAt) {
  const day = String(placedAt).slice(0, 10);
  let best = null;
  for (const k of Object.keys(ctx.files)) {
    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
    if (!m) continue;
    const from = String(jsonOf(ctx.files[k])?.effectiveFrom ?? '');
    if (from && from <= day && (!best || from > best.from)) best = { dir: m[1], from };
  }
  return best?.dir ?? null;
}

function rulesOf(ctx, ed) {
  const f = p => jsonOf(ctx.files[p]);
  return {
    fees: mapOf(f(`rulebook/${ed}/shipping-fees.json`), ['location', 'locationId'], ['feeMinor']),
    codes: mapOf(f(`rulebook/${ed}/carrier-codes.json`), ['code'], ['meaning']),
    policy: f(`rulebook/${ed}/policy.json`) ?? {},
  };
}

// Which event this is, from its payload (routing is by channel; the business kind is read here).
function kindOf(ev) {
  const p = ev.payload ?? {};
  if (ev.type === 'effect.result' || ev.type === 'timer.fired' || String(ev.type).startsWith('humanTask.')) return 'owned';
  if (p.orderId !== undefined && Array.isArray(p.items)) return 'placed';
  if (p.orderRef !== undefined && p.action !== undefined) return 'customer';
  if (p.fulfilmentRef !== undefined && p.code !== undefined) return 'carrier';
  return 'other';
}

export function tick(input, ctx) {
  const st = input.state ?? { o: null };
  const me = input.instance;
  let subject = st.o?.id ?? null;

  // --- a new instance started by an inbound message (§3.2): merge it into its order's case, or start one
  const openFor = oid => rowsOf(ctx.instances({ subject: oid })).map(x => (typeof x === 'string' ? x : x?.instance))
    .filter(x => x && x !== me);

  // --- the order record: st.o = { id, customerId, currency, p, ed, email, reviewHours, actionHours, fs, coll, phase, cleared, ended }
  const o = () => st.o;

  function startOrder(ev) {
    const p = ev.payload;
    const oid = norm(p.orderId);
    const ed = editionAt(ctx, p.placedAt);
    const r = rulesOf(ctx, ed);
    const cust = mapOf(jsonOf(ctx.files['master/customers.json']), ['customerId', 'id'], ['email']);
    const cat = mapOf(jsonOf(ctx.files['master/catalog.json']), ['sku'], ['unitPriceMinor']);
    const prices = {};
    for (const it of p.items ?? []) if (cat[it.sku] !== undefined) prices[it.sku] = cat[it.sku];
    st.o = { id: oid, customerId: p.customerId, currency: p.currency, p: p.placedAt, ed, email: cust[p.customerId] ?? '',
      reviewHours: r.policy.fraudReviewHours, actionHours: r.policy.customerActionHours, fs: {}, coll: {}, phase: 'allocating',
      cleared: false, ended: null };
    ctx.call('intake', oid, { op: 'place', orderId: oid, customerId: p.customerId, placedAt: p.placedAt, currency: p.currency,
      items: p.items, prices, fees: r.fees });
    subject = oid;
  }

  // R2.2: a review task opens (its deadline is fixed from this first task)
  function openReview(at) {
    const x = o();
    if (x.ended || x.cleared || x.phase === 'review') return;
    x.phase = 'review';
    ctx.call('review', x.id, { op: 'open', orderId: x.id, reviewHours: x.reviewHours, at });
  }

  // R3.1 or R4.1: the order is cleared at t; with unavailable items the customer is asked first
  function clearAt() {
    const x = o();
    if (x.ended || x.cleared) return;
    x.cleared = true;
    if (Object.values(x.fs).some(f => !f.avail)) {
      x.phase = 'waiting';
      ctx.call('wait', x.id, { op: 'arm', orderId: x.id, p: x.p, customerActionHours: x.actionHours, email: x.email,
        fulfilments: Object.entries(x.fs).map(([fulfilmentId, f]) => ({ fulfilmentId, available: f.avail })) });
    } else startProcessing();
  }

  // R4.1: the order and every available fulfilment become processing; each fulfilment's saga starts
  function startProcessing() {
    const x = o();
    x.phase = 'processing';
    ctx.call('close', x.id, { op: 'processing', orderId: x.id });
    for (const [fid, f] of Object.entries(x.fs)) {
      if (!f.avail || f.status !== 'pending') continue;
      f.status = 'processing';
      ctx.call('fulfil', `${x.id}.${fid}`, { op: 'start', orderId: x.id, fid, location: f.loc, customerId: x.customerId,
        email: x.email, currency: x.currency, amountMinor: f.amt, items: f.items });
    }
  }

  // R6.1, R6.2, R6.4, S15: the order is cancelled: started fulfilments compensated, the rest set cancelled, the order too
  function cancelOrder(reason, at) {
    const x = o();
    if (x.ended) return;
    x.ended = 'cancelled';
    x.phase = 'ended';
    for (const [fid, f] of Object.entries(x.fs)) {
      if (TERMINAL.includes(f.status)) continue;
      if (f.status === 'processing') {
        const r = ctx.call('fulfil', `${x.id}.${fid}`, { op: 'compensate', reason: 'cancelled' });
        f.status = r?.phase ?? 'cancelled';
      } else {
        f.status = 'cancelled';
        ctx.emit(fitArgs({ key: `fs-cancel-${fid}`, system: 'orders', op: 'setStatus', args: { orderId: x.id, fulfilmentId: fid, status: 'cancelled' } }, ctx.files));
      }
    }
    ctx.call('close', x.id, { op: 'cancel', orderId: x.id, email: x.email, reason, at });
  }

  // R6.2: a collection report (meaning collected, inTransit or delivered) at or before t proves collection (S7)
  const collectedBy = at => Object.values(o().coll).some(r => ms(r) <= ms(at));

  // R4.5: once every fulfilment has ended, the order's outcome
  function maybeOutcome() {
    const x = o();
    if (x.ended || x.phase !== 'processing') return;
    const statuses = Object.values(x.fs).map(f => f.status);
    if (!statuses.every(s => TERMINAL.includes(s))) return;
    const r = ctx.call('close', x.id, { op: 'outcome', orderId: x.id, statuses });
    if (r?.phase === 'final') { x.ended = r.status; x.phase = 'ended'; }
  }

  function applyFulfil(fid, out) {
    const f = o().fs[fid];
    if (!f) return;
    if (PHASE_STATUS[out?.phase]) f.status = PHASE_STATUS[out.phase];
    maybeOutcome();
  }

  // Results, timers and human-task events: delivered to the module instance that caused them
  function deliverOwned(ev) {
    const x = o();
    const own = ctx.ownerOf(ev);
    if (!own || !x) return;
    const out = ctx.deliver(ev) ?? {};
    if (own.module === 'intake') {
      if (out.phase === 'recorded') {
        for (const f of out.fulfilments) x.fs[f.fulfilmentId] = { loc: f.location, amt: f.amountMinor, items: f.items,
          avail: f.available, status: f.available ? 'pending' : 'unavailable' };
        x.phase = 'checking';
      }
      if (out.phase === 'verdict') {
        if (out.verdict === 'pass') clearAt();                              // R2.1: cleared at p
        else if (out.verdict === 'reject') cancelOrder('fraud', ev.at);      // R2.1: cancel within 120 min of p
        else openReview(ev.at);                                              // R2.1: review
      }
    } else if (own.module === 'review') {
      if (out.phase === 'approved') clearAt();
      else if (out.phase === 'rejected') cancelOrder('fraud', out.at ?? ev.at);
      else if (out.phase === 'timed-out') cancelOrder('fraud-review-timeout', out.at ?? ev.at);
    } else if (own.module === 'wait') {
      if (out.timedOut) {
        for (const f of Object.values(x.fs)) f.status = 'cancelled';
        x.ended = 'timedOut';
        x.phase = 'ended';
      }
    } else if (own.module === 'fulfil') {
      applyFulfil(own.key.slice(x.id.length + 1), out);
    } else if (own.module === 'close' && out.phase === 'final') {
      x.ended = out.status;
      x.phase = 'ended';
    }
  }

  // §3.3 customer actions (S5, S8, S11, R3.2, R6.2, R6.3, R6.4)
  function onCustomer(ev) {
    const x = o();
    const p = ev.payload;
    if (!x || x.id !== norm(p.orderRef) || x.ended) return;
    if (p.action === 'cancel') {
      if (!x.cleared) return cancelOrder('customer', ev.at);                // R6.4: fraud review open
      if (x.phase === 'waiting') {
        const w = ctx.call('wait', x.id, { op: 'action', at: ev.at, action: 'cancel' });
        if (w?.counted === 'cancel') cancelOrder('customer', ev.at);
        return;
      }
      if (x.phase === 'processing') {
        if (collectedBy(ev.at)) return ctx.call('close', x.id, { op: 'refuse', orderId: x.id, ref: ev.id, email: x.email });
        return cancelOrder('customer', ev.at);                              // R6.2
      }
      return;
    }
    if (p.action === 'amend' && x.phase === 'waiting') {
      const w = ctx.call('wait', x.id, { op: 'action', at: ev.at, action: 'amend' });
      if (w?.counted !== 'amend') return;
      for (const f of Object.values(x.fs)) if (!f.avail) f.status = 'cancelled';
      if (w.nothingAvailable) return cancelOrder('nothing-available', ev.at);   // R3.2
      startProcessing();                                                       // ready at a (R4)
    }
  }

  // §3.3 carrier messages (R4.4): routed to the fulfilment by its fulfilmentRef
  function onCarrier(ev) {
    const x = o();
    const p = ev.payload;
    if (!x || !x.fs[p.fulfilmentRef]) return;
    const meaning = rulesOf(ctx, x.ed).codes[p.code] ?? 'info';              // a code not listed is info
    if (COLLECTED.includes(meaning) && (!x.coll[p.fulfilmentRef] || ms(p.reportedAt) < ms(x.coll[p.fulfilmentRef]))) {
      x.coll[p.fulfilmentRef] = p.reportedAt;
    }
    const out = ctx.call('fulfil', `${x.id}.${p.fulfilmentRef}`, { op: 'carrier', meaning, reportedAt: p.reportedAt });
    applyFulfil(p.fulfilmentRef, out);
  }

  // The first tick of an instance started by a message: placed orders start one; anything else merges into the open
  // case of its order or closes (S11: an action that names no order yet changes nothing)
  function freshMessage(k, ev) {
    const p = ev.payload;
    const oid = k === 'placed' ? norm(p.orderId) : k === 'customer' ? norm(p.orderRef)
      : rowsOf(ctx.query('orders.fulfilments', { where: { fulfilmentId: p.fulfilmentRef }, limit: 1 }))[0]?.orderId;
    const target = oid ? openFor(norm(oid))[0] : undefined;
    if (target) return { decisions: { subject: norm(oid) }, state: null, merge: { into: target } };
    if (k === 'placed') { startOrder(ev); return null; }
    return { decisions: { subject: oid ? norm(oid) : null }, state: null, close: true };
  }

  for (const ev of input.events ?? []) {
    const k = kindOf(ev);
    if (k === 'owned') { deliverOwned(ev); continue; }
    if (!st.o && (k === 'placed' || k === 'customer' || k === 'carrier')) {
      const early = freshMessage(k, ev);
      if (early) return early;
      continue;
    }
    if (k === 'customer') onCustomer(ev);
    else if (k === 'carrier') onCarrier(ev);
    // a repeated placed order (R1.4) and any other message: no effect
  }
  return { decisions: { subject }, state: st };
}
----
// intake: R1 (record the order once, with its amounts) and the R2.1 fraud check that follows it.
// Keys are local: 'allocate', 'create', 'fraud'. The parent passes the price and fee tables it read from the rulebook.

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);

// A result payload: the read result is whatever object the platform put beside the status.
const resultOf = p => {
  for (const k of ['result', 'data', 'value', 'output']) if (isObj(p?.[k])) return p[k];
  return isObj(p) ? p : {};
};

// R1.2: amountMinor = sum(qty * unitPriceMinor) + the location's fee (none when the location is null).
export function priceFulfilment(f, prices, fees) {
  let sum = 0;
  for (const it of f.items ?? []) sum += (it.qty ?? 0) * (prices[it.sku] ?? 0);
  const fee = f.location === null || f.location === undefined ? 0 : (fees[f.location] ?? 0);
  return sum + fee;
}

function stepRaw(input, ctx) {
  if (input.op !== 'place') return { output: null };
  const st = { orderId: input.orderId, customerId: input.customerId, placedAt: input.placedAt, currency: input.currency,
    items: input.items, prices: input.prices, fees: input.fees };
  return {
    state: st,
    effects: [{ key: 'allocate', system: 'inventory', op: 'allocate', args: { orderId: input.orderId } }],
    output: { phase: 'allocating' },
  };
}

function onEventRaw(event, ctx) {
  const st = ctx.state;
  if (event?.type !== 'effect.result' || !st) return { output: null };
  const p = event.payload ?? {};
  if (p.key === 'allocate') {
    if (p.status !== 'ok') return { output: { phase: 'allocate-failed', status: p.status } };
    const plan = resultOf(p);
    const fulfilments = (plan.fulfilments ?? []).map(f => {
      const row = { fulfilmentId: f.fulfilmentId, location: f.location ?? null, items: (f.items ?? []).map(i => ({ sku: i.sku, qty: i.qty })), available: f.available !== false };
      return { ...row, amountMinor: priceFulfilment(row, st.prices, st.fees) };
    });
    const totalMinor = fulfilments.reduce((s, f) => s + f.amountMinor, 0);
    const create = { orderId: st.orderId, customerId: st.customerId, placedAt: st.placedAt, currency: st.currency,
      items: st.items, fulfilments: fulfilments.map(({ available, ...f }) => f), totalMinor };
    return {
      state: { ...st, fulfilments, totalMinor },
      effects: [
        { key: 'create', system: 'orders', op: 'create', args: create },
        { key: 'fraud', system: 'fraud', op: 'check', args: { orderId: st.orderId } },
      ],
      output: { phase: 'recorded', fulfilments, totalMinor },
    };
  }
  if (p.key === 'create') return { output: { phase: 'created', status: p.status } };
  if (p.key === 'fraud') {
    if (p.status !== 'ok') return { output: { phase: 'fraud-failed', status: p.status } };
    const verdict = resultOf(p).verdict ?? p.verdict ?? null;
    return { output: { phase: 'verdict', verdict } };
  }
  return { output: null };
}

// The API may rename a field: api/<system>.schema.json in ctx.files shows the current names, so send those.
const fitNorm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
function fitArgs(e, files) {
  const sch = files?.[`api/${e.system}.schema.json`];
  const props = (typeof sch === 'string' ? JSON.parse(sch) : sch)?.ops?.[e.op]?.args?.properties;
  if (!props || e.args === null || typeof e.args !== 'object' || Array.isArray(e.args)) return e;
  const names = Object.keys(props);
  const keys = Object.keys(e.args);
  const extra = keys.filter(k => !names.includes(k));
  const missing = names.filter(n => !keys.includes(n));
  const renamed = {};
  for (const k of extra) renamed[k] = names.find(n => fitNorm(n) === fitNorm(k)) ?? (extra.length === 1 && missing.length === 1 ? missing[0] : k);
  const args = {};
  for (const k of keys) args[renamed[k] ?? k] = e.args[k];
  return { ...e, args };
}
function fitAll(res, files) {
  if (res === null || typeof res !== 'object' || !Array.isArray(res.effects)) return res;
  return { ...res, effects: res.effects.map(e => fitArgs(e, files)) };
}
export function step(input, ctx) { return fitAll(stepRaw(input, ctx), ctx.files); }
export function onEvent(event, ctx) { return fitAll(onEventRaw(event, ctx), ctx.files); }
// fulfil: one fulfilment's saga (R4.2 reserve, charge, ship), its carrier messages (R4.4), and its compensation (R5.1).
// Keys: 'charge', 'ship', 'status-<to>', 'notice', and the undo keys 'release-<item>', 'refund', 'ship-cancel'. The reserve
// batch has no key of its own: its items are r0, r1, ... The parent calls op 'start' when the order is ready, 'carrier'
// for each report about this fulfilment, and 'compensate' when the order is cancelled.

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const jsonOf = f => (typeof f === 'string' ? JSON.parse(f) : (f ?? null));
const INVALID = ['invalid-args', 'field-renamed'];      // our request was wrong: correct it and re-issue (R4.2)
const MAX_BAD = 3;
const MAX_RESUBMIT = 5;

// The API may rename a field: api/<system>.schema.json in ctx.files shows the current names, so send those.
const nrm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
function fitArgs(e, files) {
  const props = jsonOf(files?.[`api/${e.system}.schema.json`])?.ops?.[e.op]?.args?.properties;
  if (!props || !isObj(e.args)) return e;
  const names = Object.keys(props);
  const keys = Object.keys(e.args);
  const extra = keys.filter(k => !names.includes(k));
  const missing = names.filter(n => !keys.includes(n));
  const renamed = {};
  for (const k of extra) renamed[k] = names.find(n => nrm(n) === nrm(k)) ?? (extra.length === 1 && missing.length === 1 ? missing[0] : k);
  const args = {};
  for (const k of keys) args[renamed[k] ?? k] = e.args[k];
  return { ...e, args };
}
function fitAll(res, files) {
  if (!isObj(res) || !Array.isArray(res.effects)) return res;
  return { ...res, effects: res.effects.map(e => fitArgs(e, files)) };
}

const setStatus = (st, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: st.orderId, fulfilmentId: st.fid, status } });
const chargeEffect = st => ({ key: 'charge', system: 'billing', op: 'charge', args: { orderId: st.orderId, fulfilmentId: st.fid, customerId: st.customerId, amountMinor: st.amountMinor, currency: st.currency } });
const shipEffect = st => ({ key: 'ship', system: 'carrier', op: 'create', args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location, ref: st.fid } });
// A batch op keys its items, not the batch: each item's key ('r0', 'r1', ...) is what its result is routed by.
const reserveEffect = st => ({
  system: 'inventory', op: 'reserve',
  args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location,
    items: st.items.filter(it => st.res[it.key] !== 'ok').map(it => ({ key: it.key, sku: it.sku, qty: it.qty })) },
});

// The compensating step for one undo key (R5.1).
function undoEffect(st, key) {
  if (key === 'refund') return { key, system: 'billing', op: 'refund', args: { orderId: st.orderId, fulfilmentId: st.fid, amountMinor: st.amountMinor }, compensates: 'charge' };
  if (key === 'ship-cancel') return { key, system: 'carrier', op: 'cancel', args: { orderId: st.orderId, fulfilmentId: st.fid }, compensates: 'ship' };
  const it = st.items.find(i => `release-${i.key}` === key);
  return it ? { key, system: 'inventory', op: 'release', args: { orderId: st.orderId, fulfilmentId: st.fid, sku: it.sku }, compensates: it.key } : null;
}

// Compensation (R5.1): cancel the shipment (not if collection failed), refund the charge, release each committed item.
// Only steps that committed and are not undone yet are undone (never twice, never a step that did not commit).
function undoSteps(st) {
  const undone = { ...st.undone };
  const keys = [];
  if (st.ship === 'ok' && !undone.ship && st.carrier !== 'collectionFailed') { keys.push('ship-cancel'); undone.ship = true; }
  if (st.charge === 'ok' && !undone.refund) { keys.push('refund'); undone.refund = true; }
  for (const it of st.items) if (st.res[it.key] === 'ok' && !undone[it.key]) { keys.push(`release-${it.key}`); undone[it.key] = true; }
  return { effects: keys.map(k => undoEffect(st, k)), undone };
}

// A step that committed after the fulfilment was cancelled or failed is compensated at once (S14, R6.2).
function lateUndo(st, phase) {
  const u = undoSteps(st);
  return { state: { ...st, undone: u.undone }, effects: u.effects, output: { phase, lateUndo: true } };
}

// Re-issue a request the system refused as invalid, with the same key (bounded).
function reissue(st, key, effect, where) {
  const bad = { ...(st.bad ?? {}), [key]: (st.bad?.[key] ?? 0) + 1 };
  if (bad[key] > MAX_BAD) return fail({ ...st, bad }, where, 'invalid-request');
  return { state: { ...st, bad }, effects: [effect], output: { phase: st.phase, reissued: key } };
}

// The outcome of one effect: unknown is decided by status(key) (S2).
const outcomeOf = (p, ctx, system) => (p.status === 'unknown' ? (ctx.status(system, p.key) === 'committed' ? 'ok' : 'error') : p.status);

// R5.2: the fulfilment fails: compensate what committed, set failed, tell the customer.
function fail(st, where, why = null) {
  if (['failed', 'cancelled', 'completed'].includes(st.phase)) return { output: { phase: st.phase } };
  const u = undoSteps(st);
  const effects = [...u.effects, setStatus(st, 'failed', 'status-failed')];
  effects.push({ key: 'notice', system: 'notify', op: 'send', args: { to: st.email ?? '', about: st.fid, template: 'fulfilment-failed', text: `Fulfilment ${st.fid} failed (${why ?? where}).` } });
  return { state: { ...st, phase: 'failed', undone: u.undone }, effects, output: { phase: 'failed', where, why } };
}

export function step(input, ctx) { return fitAll(stepRaw(input, ctx), ctx.files); }

function stepRaw(input, ctx) {
  const st = ctx.state;
  if (input.op === 'start') {
    if (st) return { output: { phase: st.phase } };
    const items = input.items.map((it, i) => ({ key: `r${i}`, sku: it.sku, qty: it.qty }));
    const next = { orderId: input.orderId, fid: input.fid, location: input.location, customerId: input.customerId, email: input.email,
      currency: input.currency, amountMinor: input.amountMinor, items, res: {}, charge: 'none', ship: 'none', carrier: null,
      phase: 'reserving', undone: {}, attempts: 0, bad: {} };
    return { state: next, effects: [setStatus(next, 'processing', 'status-processing'), reserveEffect(next)], output: { phase: 'reserving' } };
  }
  if (!st) return { output: { phase: 'none' } };
  if (input.op === 'carrier') return carrier(input.meaning, input.reportedAt, st, ctx);
  if (input.op === 'compensate') return cancelFulfilment(st, input.reason);
  return { output: { phase: st.phase } };
}

// R4.4: a carrier report about this fulfilment. Reports about a finished or cancelled fulfilment change nothing.
function carrier(meaning, reportedAt, st) {
  const open = ['reserving', 'charging', 'shipping', 'shipped', 'dispatched'].includes(st.phase);
  if (!open || st.ship !== 'ok') return { output: { phase: st.phase, changed: false } };
  if (meaning === 'collected') {
    if (st.phase !== 'shipped') return { output: { phase: st.phase, changed: false } };
    return { state: { ...st, phase: 'dispatched', collected: reportedAt }, effects: [setStatus(st, 'dispatched', 'status-dispatched')], output: { phase: 'dispatched', collected: true } };
  }
  if (meaning === 'delivered') {
    const effects = st.phase === 'dispatched' ? [] : [setStatus(st, 'dispatched', 'status-dispatched')];
    effects.push(setStatus(st, 'completed', 'status-completed'));
    return { state: { ...st, phase: 'completed' }, effects, output: { phase: 'completed', collected: true } };
  }
  if (meaning === 'collectionFailed') return fail({ ...st, carrier: 'collectionFailed' }, 'carrier', 'collection-failed');
  return { output: { phase: st.phase, changed: false } };       // inTransit, info
}

// R6.1 / R6.2: the order is cancelled; this fulfilment is compensated and set cancelled.
function cancelFulfilment(st, reason) {
  if (['completed', 'failed', 'cancelled'].includes(st.phase)) return { output: { phase: st.phase, changed: false } };
  const next = { ...st, phase: 'cancelled' };
  const u = undoSteps(next);
  return { state: { ...next, undone: u.undone }, effects: [...u.effects, setStatus(next, 'cancelled', 'status-cancelled')], output: { phase: 'cancelled', reason } };
}

export function onEvent(event, ctx) { return fitAll(onEventRaw(event, ctx), ctx.files); }

function onEventRaw(event, ctx) {
  const st = ctx.state;
  if (!st) return { output: { phase: 'none' } };
  if (event?.type === 'effect.result') return onResult(event.payload ?? {}, st, ctx);
  return { output: { phase: st.phase } };
}

function onResult(p, st, ctx) {
  if (Array.isArray(p.items) || p.key === 'reserve') return onReserve(p, st);
  if (p.key === 'charge') return onCharge(p, st, ctx);
  if (p.key === 'ship') return onShip(p, st, ctx);
  // an undo step refused as invalid on our request: correct it and re-issue
  if (p.status === 'error' && INVALID.includes(p.error?.code) && undoEffect(st, p.key)) return reissue(st, p.key, undoEffect(st, p.key), 'undo');
  return { output: { phase: st.phase } };
}

// R4.2 reserve: committed items stay, failed ones are resubmitted with their original keys inside the window.
function onReserve(p, st) {
  const next = { ...st, res: { ...st.res } };
  if (p.status === 'ok') for (const it of st.items) next.res[it.key] = 'ok';
  if (Array.isArray(p.items)) for (const it of p.items) if (it?.status === 'ok' && it.key) next.res[it.key] = 'ok';
  if (p.status === 'error' && INVALID.includes(p.error?.code)) return reissue(next, 'reserve', reserveEffect(next), 'reserve');
  if (p.status === 'error' && p.error?.code !== 'batch-item-not-processed') return fail(next, 'reserve', p.error?.code ?? 'error');
  if (st.phase !== 'reserving') return lateUndo(next, st.phase);
  const flagged = next.items.filter(it => next.res[it.key] !== 'ok');
  if (!flagged.length) return { state: { ...next, phase: 'charging' }, effects: [chargeEffect(next)], output: { phase: 'charging' } };
  if (next.attempts >= MAX_RESUBMIT) return fail(next, 'reserve', 'reserve-exhausted');
  const again = { ...next, attempts: next.attempts + 1 };
  return { state: again, effects: [reserveEffect(again)], output: { phase: 'reserving', resubmitted: flagged.length } };
}

function onCharge(p, st, ctx) {
  if (p.status === 'error' && INVALID.includes(p.error?.code)) return reissue(st, 'charge', chargeEffect(st), 'charge');
  if (p.status === 'error') return fail({ ...st, charge: 'declined' }, 'charge', p.error?.code ?? 'error');
  const s = outcomeOf(p, ctx, 'billing');
  if (s === 'error') return fail({ ...st, charge: 'declined' }, 'charge', 'unknown');
  if (s !== 'ok') return { output: { phase: st.phase } };
  const next = { ...st, charge: 'ok' };
  if (st.phase !== 'charging') return lateUndo(next, st.phase);
  return { state: { ...next, phase: 'shipping' }, effects: [shipEffect(st)], output: { phase: 'shipping' } };
}

function onShip(p, st, ctx) {
  if (p.status === 'error' && INVALID.includes(p.error?.code)) return reissue(st, 'ship', shipEffect(st), 'ship');
  if (p.status === 'error') return fail({ ...st, ship: 'error' }, 'ship', p.error?.code ?? 'error');
  const s = outcomeOf(p, ctx, 'carrier');
  if (s === 'error') return fail({ ...st, ship: 'error' }, 'ship', 'unknown');
  if (s !== 'ok') return { output: { phase: st.phase } };
  const next = { ...st, ship: 'ok' };
  if (st.phase !== 'shipping') return lateUndo(next, st.phase);
  return { state: { ...next, phase: 'shipped' }, output: { phase: 'shipped' } };
}

